CONC.editais = {};
CONC.editais.ipam = {"titulo": "Edital IPAM nº 01/2026 (IBADE) — publicado em 29/10/2026", "fonte": "Diário Oficial dos Municípios de Rondônia, edição extraordinária nº 4350a (29/10/2026)", "link": "https://www.ibade.org.br", "linkIpam": "https://ipam.portovelho.ro.gov.br", "inscricao": {"ini": "2026-11-03T10:00:00-04:00", "fim": "2026-12-07T23:59:00-04:00", "pagamento": "08/12/2026", "isencao": "05/11 e 06/11/2026", "taxa": {"medio": 105, "superior": 140}}, "etapas": {"medio": ["Prova Objetiva (eliminatória e classificatória)"], "superior": ["Prova Objetiva (eliminatória e classificatória)", "Prova Discursiva (2 questões, 100 pontos, eliminatória e classificatória)", "Prova de Títulos (online, classificatória)"]}, "estrutura": {"medio": [["Língua Portuguesa", 10, 1, "portugues"], ["Raciocínio Lógico e Matemático", 5, 1, "logica"], ["Informática Básica", 5, 1, "pf-info"], ["Noções de Administração Pública, Atendimento e Ética", 5, 1, "pf-adm"], ["Noções de Legislação Institucional, Previdenciária e de Assistência à Saúde", 5, 1, "previdencia"], ["Conhecimentos Específicos (do seu cargo)", 50, 2, null]], "superior": [["Língua Portuguesa", 10, 1, "portugues"], ["Raciocínio Lógico e Matemático", 5, 1, "logica"], ["Informática Básica", 5, 1, "pf-info"], ["Administração Pública, Governança e Ética", 5, 1, "pf-adm"], ["Noções de Direito Administrativo, Constitucional e Previdenciário", 5, 1, "previdencia"], ["Conhecimentos Específicos (do seu cargo)", 50, 2, null]]}, "minimo": 0.5, "naoZerar": true, "totalPontos": 130, "regras": ["Prova objetiva: 80 questões de múltipla escolha, 5 alternativas, só 1 correta (item 11.1.1). Tempo: 4 horas, já incluindo o preenchimento do Cartão de Respostas (10.21).", "Eliminação (item 11.6): quem tirar menos de 50% dos pontos da objetiva (65 de 130), OU zero em qualquer disciplina, OU ficar fora do posicionamento do seu cargo (tabela abaixo).", "Peso: as 30 questões gerais valem 1 ponto cada (30 pontos); as 50 específicas valem 2 pontos cada (100 pontos). Os Específicos são 77% da nota.", "Cartão de Respostas: uma única opção por questão; marcação dupla, em branco, emenda ou rasura vale zero (11.9). Não há substituição do cartão (11.8).", "Marque o TIPO DE PROVA no cartão igual ao do caderno: sem isso o cartão não é lido e você é eliminado (11.8.1). Transcreva a frase do Exame Grafotécnico antes de começar (11.4).", "Não há desconto de nota por erro previsto no edital: marque todas as questões.", "Caneta esferográfica de material transparente, de preferência tinta preta; tinta azul pode falhar na leitura do cartão (10.5).", "Documento oficial original com foto, com 1 hora de antecedência ao fechamento dos portões; os portões fecham e a prova começa 20 minutos depois (10.5.1 e 10.6).", "Celular e eletrônicos (inclusive relógio) desligados e lacrados no envelope; se tocar ou sair do envelope, eliminação (10.16 m, n). Calculadora e consulta também eliminam (10.16 p).", "Só pode sair após 1 hora do início; só leva o caderno se sair na última hora (10.21.2 e 10.21.3). Anotações só no caderno de questões (10.23).", "Gabarito no 2º dia útil após a prova, a partir das 12h; recursos nos 2 dias seguintes (Anexo II)."], "desempate": {"medio": ["Maior nota em Conhecimentos Específicos", "Maior nota em Língua Portuguesa", "Maior nota em Legislação Institucional, Previdenciária e de Assistência à Saúde", "Maior nota em Raciocínio Lógico e Matemático", "Maior nota em Administração Pública, Atendimento e Ética", "Ter sido jurado (Lei 11.689/2008)", "Candidato mais velho"], "superior": ["Maior nota em Conhecimentos Específicos", "Maior nota em Língua Portuguesa", "Maior nota em Direito Administrativo, Constitucional e Previdenciário", "Maior nota em Raciocínio Lógico e Matemático", "Maior nota em Administração Pública, Governança e Ética", "Ter sido jurado (Lei 11.689/2008)", "Candidato mais velho"]}, "idosoPrimeiro": true, "cronograma": {"geral": [["03/11 a 07/12/2026", "Inscrições pela internet (site do IBADE)"], ["05/11 e 06/11/2026", "Pedido de isenção da taxa"], ["24/11/2026", "Resultado dos pedidos de isenção"], ["08/12/2026", "Último dia para pagar o boleto"], ["15/12/2026", "Atendimento especial deferido e inscrições para vagas reservadas"], ["29/12/2026", "Homologação das inscrições"]], "medio": [["15/02/2027", "Convocação para a prova (COCP)"], ["21/02/2027", "PROVA OBJETIVA"], ["23/02/2027", "Gabarito preliminar (a partir das 12h)"], ["24/02 e 25/02/2027", "Recursos contra o gabarito"], ["30/03/2027", "Resultado preliminar da objetiva"], ["09/04/2027", "Resultado final da objetiva"], ["28/07/2027", "Resultado final do concurso"]], "superior": [["22/02/2027", "Convocação para as provas (COCP)"], ["28/02/2027", "PROVAS OBJETIVA E DISCURSIVA"], ["02/03/2027", "Gabarito preliminar (a partir das 12h)"], ["03/03 e 04/03/2027", "Recursos contra o gabarito"], ["14/04/2027", "Resultado preliminar da objetiva"], ["26/04 e 27/04/2027", "Envio dos títulos"], ["04/05/2027", "Resultado preliminar da discursiva"], ["28/07/2027", "Resultado final do concurso"]]}, "conteudoGeral": {"medio": {"LÍNGUA PORTUGUESA": "Leitura, compreensão e interpretação de textos verbais e não verbais de diferentes gêneros. Identificação de tema, tese, finalidade, informações explícitas e implícitas, pressupostos e inferências. Tipologia e gêneros textuais. Coerência, coesão, referenciação, conectores e progressão textual. Relações semânticas: sinonímia, antonímia, polissemia, homonímia, paronímia, denotação e conotação. Figuras de linguagem. Ortografia oficial, emprego de letras, acentuação gráfica e uso do hífen. Classes de palavras e seus empregos no texto. Estrutura e formação de palavras. Flexão nominal e verbal. Emprego de tempos e modos verbais. Termos da oração. Período simples e composto. Coordenação e subordinação. Concordância nominal e verbal. Regência nominal e verbal. Emprego do sinal indicativo de crase. Colocação pronominal. Pontuação. Reescrita de frases e parágrafos com preservação do sentido. Variação linguística, adequação vocabular e norma-padrão.", "RACIOCÍNIO LÓGICO E MATEMÁTICO": "Estruturas lógicas e relações entre pessoas, objetos, lugares e eventos. Proposições, conectivos, negações, equivalências, implicações e tabelas- verdade. Argumentação lógica, validade de argumentos e diagramas. Conjuntos e operações. Números inteiros, racionais e reais. Operações fundamentais, frações e números decimais. Razão, proporção, regra de três simples e composta. Porcentagens, acréscimos e descontos. Equações e sistemas de primeiro grau. Grandezas e medidas. Sequências numéricas e padrões. Princípios básicos de contagem, arranjos, combinações e probabilidade. Média aritmética e leitura de dados. Interpretação de tabelas, gráficos e informações quantitativas. Resolução de problemas envolvendo situações do cotidiano e do serviço público.", "INFORMÁTICA BÁSICA": "Conceitos de hardware, software, periféricos e armazenamento. Sistemas operacionais Windows 10 e 11: área de trabalho, janelas, configurações, gerenciamento de arquivos e pastas, atalhos, pesquisa, instalação e remoção de programas e impressão. Noções de Linux. Suítes Microsoft Office / Microsoft 365 e LibreOffice: edição e formatação de textos; planilhas eletrônicas, fórmulas, funções, referências, filtros e gráficos; apresentações. Internet e intranet. Navegadores, mecanismos de busca, correio eletrônico, calendários e ferramentas de colaboração e armazenamento em nuvem. Formatos de arquivos, compactação e compartilhamento. Segurança da informação: senhas, autenticação multifator, malware, phishing, navegação segura, atualizações, antivírus, firewall, cópias de segurança e recuperação de dados. Noções de certificado e assinatura digital. Boas práticas de proteção de dados pessoais no uso de recursos computacionais.", "NOÇÕES DE ADMINISTRAÇÃO PÚBLICA, ATENDIMENTO E ÉTICA": "Princípios constitucionais da Administração Pública. Administração direta e indireta. Autarquias. Agentes públicos: direitos, deveres, responsabilidades e condutas. Noções de atos administrativos e poderes administrativos. Serviços públicos e atendimento ao cidadão. Comunicação no ambiente de trabalho. Qualidade, eficiência, organização, trabalho em equipe, gestão do tempo e solução de conflitos. Noções de planejamento, processos e rotinas administrativas. Protocolo, tramitação e organização de documentos. Ética, integridade, interesse público, impessoalidade, transparência e prestação de contas. Acesso à informação e proteção de dados pessoais: Lei Federal nº 12.527/2011 e Lei Federal nº 13.709/2018. Noções da Lei Federal nº 14.133/2021: princípios, agentes, fases básicas da contratação, fiscalização e gestão contratual. Redação oficial: finalidade, clareza, concisão, formalidade, padronização e principais documentos administrativos.", "NOÇÕES DE LEGISLAÇÃO INSTITUCIONAL, PREVIDENCIÁRIA E DE ASSISTÊNCIA À SAÚDE": "Constituição Federal: Administração Pública e servidores públicos (arts. 37 a 41, com destaque para o art. 40); custeio da seguridade social (art. 149 e parágrafos). Emenda Constitucional nº 103/2019: dispositivos aplicáveis aos regimes próprios de previdência social dos Municípios. Lei Federal nº 9.717/1998: normas gerais de organização e funcionamento dos Regimes Próprios de Previdência Social. Lei Federal nº 10.887/2004: base de cálculo da contribuição e cálculo dos proventos, no que aplicável ao RPPS municipal. Portaria MTP nº 1.467/2022 e alterações posteriores: conceitos gerais, filiação, segurados, dependentes e regras de custeio, em nível compatível com o cargo. Legislação do Município de Porto Velho: Lei Complementar Municipal nº 385/2010 e alterações posteriores (Regime Jurídico dos Servidores Públicos Municipais), limitada a provimento, vacância, direitos e vantagens, deveres, proibições, responsabilidades, regime disciplinar e processo administrativo disciplinar; Lei Complementar Municipal nº 404/2010 e alterações posteriores (Regime Próprio de Previdência Social — RPPS/IPAM), quanto a finalidades, segurados, dependentes, benefícios e custeio; Lei Complementar Municipal nº 841/2021 (serviço de Assistência à Saúde e Fundo de Assistência à Saúde — FAS), quanto a filiação, usuários, dependentes, custeio e utilização dos serviços; Lei Complementar Municipal nº 866/2021 e alterações posteriores (Plano de Carreira, Cargos e Remuneração do IPAM), quanto ao quadro técnico, ingresso e atribuições dos cargos; Lei Complementar Municipal nº 870/2021 (Regime de Previdência Complementar), quanto a conceito, abrangência e adesão; Lei Complementar Municipal nº 886/2022 e alterações posteriores (organização do IPAM), quanto a finalidade, estrutura organizacional e competências institucionais."}, "superior": {"LÍNGUA PORTUGUESA": "Compreensão, interpretação e análise de textos de diferentes gêneros e níveis de formalidade. Organização discursiva, estrutura argumentativa, tese, pressupostos, implícitos e inferências. Tipologia e gêneros textuais. Coerência e coesão; mecanismos de referenciação, substituição, elipse, conectores e progressão temática. Intertextualidade. Semântica lexical e textual; sinonímia, antonímia, polissemia, ambiguidade, denotação, conotação e figuras de linguagem. Ortografia oficial e acentuação. Classes de palavras e valores morfossintáticos. Processos de formação de palavras. Flexões nominal e verbal. Sintaxe do período simples e composto. Coordenação, subordinação, correlação e paralelismo. Concordância nominal e verbal. Regência nominal e verbal. Crase. Colocação pronominal. Pontuação e efeitos de sentido. Emprego de tempos, modos e vozes verbais. Reescrita, equivalência e transformação de estruturas. Variação linguística, adequação vocabular, precisão, clareza, concisão e norma- padrão. Aspectos linguísticos da redação administrativa e oficial.", "RACIOCÍNIO LÓGICO E MATEMÁTICO": "Lógica proposicional: proposições, conectivos, negação, equivalência, implicação, tautologia, contradição e tabelas-verdade. Lógica de argumentação, regras de inferência, validade e diagramas lógicos. Relações, ordenações e problemas de associação. Conjuntos, operações e diagramas. Razões, proporções, porcentagens, taxas e variações. Equações, sistemas e funções elementares. Sequências e padrões. Análise combinatória e probabilidade. Estatística descritiva: distribuição de frequências, médias, mediana, moda, medidas de dispersão e interpretação de indicadores. Leitura crítica de tabelas e gráficos. Resolução de problemas quantitativos e interpretação de informações numéricas.", "INFORMÁTICA BÁSICA": "Conceitos de tecnologia da informação, hardware, software, sistemas operacionais e redes. Windows 10 e 11 e noções de Linux. Gerenciamento de arquivos, permissões e recursos do sistema. Microsoft Office / Microsoft 365 e LibreOffice: processamento de textos, estilos, tabelas e revisão; planilhas, fórmulas, funções, referências, tabelas dinâmicas, filtros e gráficos; apresentações e recursos colaborativos. Internet, intranet, navegadores, correio eletrônico, pesquisa e armazenamento em nuvem. Ferramentas de videoconferência e trabalho colaborativo. Formatos, compactação, compartilhamento e versionamento básico de arquivos. Segurança da informação: confidencialidade, integridade, disponibilidade, autenticidade, controle de acesso, autenticação multifator, phishing, malware, ransomware, criptografia, firewall, antivírus, atualização, backup e recuperação. Certificados e assinaturas digitais. Noções de proteção de dados pessoais e boas práticas relacionadas à Lei Geral de Proteção de Dados.", "ADMINISTRAÇÃO PÚBLICA, GOVERNANÇA E ÉTICA": "Administração Pública: princípios, modelos de administração pública e organização administrativa. Administração direta e indireta; autarquias. Governança pública, capacidade de resposta, integridade, confiabilidade, melhoria regulatória, transparência e prestação de contas. Planejamento estratégico e institucional; missão, visão, objetivos, indicadores, metas, monitoramento e avaliação. Gestão por processos e melhoria contínua. Gestão de riscos e controles internos. Gestão de projetos. Gestão de pessoas no setor público, competências, liderança, desempenho e desenvolvimento. Gestão da qualidade e foco no usuário do serviço público. Inovação e transformação digital. Ética pública, conflito de interesses, integridade e prevenção de desvios. Lei Federal nº 12.527/2011 (Acesso à Informação) e Lei Federal nº 13.709/2018 (Proteção de Dados Pessoais): objeto, princípios, diretrizes e obrigações da Administração. Governança das contratações públicas: planejamento, gestão de riscos, fiscalização e gestão contratual, em perspectiva gerencial, sendo a disciplina normativa da Lei Federal nº 14.133/2021 objeto do bloco seguinte. Responsabilização e prestação de contas.", "NOÇÕES DE DIREITO ADMINISTRATIVO, CONSTITUCIONAL E PREVIDENCIÁRIO": "Constituição Federal: princípios fundamentais; direitos e garantias fundamentais; organização do Estado; Administração Pública e servidores públicos (arts. 37 a 41, com destaque para o art. 40); fiscalização contábil, financeira e orçamentária (arts. 70 a 75); custeio da seguridade social (art. 149); seguridade social (arts. 194 a 204). Emenda Constitucional nº 103/2019: dispositivos aplicáveis aos regimes próprios de previdência social dos Municípios. Direito Administrativo: princípios; organização administrativa; autarquias; poderes e deveres da Administração; atos administrativos; agentes públicos; serviços públicos; responsabilidade civil do Estado; processo administrativo; controle da Administração; transparência, acesso à informação e proteção de dados pessoais, no recorte delimitado no bloco anterior. Improbidade administrativa: conceito, sujeitos, espécies de atos ímprobos (arts. 9º, 10 e 11) e sanções, nos termos da Lei Federal nº 8.429/1992, com as alterações da Lei Federal nº 14.230/2021. Licitações e contratos administrativos: Lei Federal nº 14.133/2021, quanto a princípios, planejamento da contratação, agentes, modalidades, critérios de julgamento, contratação direta, contratos, execução, alteração, extinção, fiscalização e sanções. Regimes Próprios de Previdência Social: Lei Federal nº 9.717/1998, Lei Federal nº 10.887/2004 e Portaria MTP nº 1.467/2022 e alterações posteriores, quanto a organização, custeio, benefícios, equilíbrio financeiro e atuarial e responsabilidades do gestor. Legislação municipal aplicável ao IPAM, nos recortes indicados: Lei Complementar Municipal nº 385/2010 e alterações posteriores (regime jurídico dos servidores, limitado a provimento, vacância, direitos e vantagens, deveres, proibições, responsabilidades, regime disciplinar e processo administrativo disciplinar); Lei Complementar Municipal nº 404/2010 e alterações posteriores (RPPS/IPAM); Lei Complementar Municipal nº 841/2021 (Assistência à Saúde e Fundo de Assistência à Saúde — FAS); Lei Complementar Municipal nº 866/2021 e alterações posteriores (Plano de Carreira, Cargos e Remuneração do IPAM); Lei Complementar Municipal nº 870/2021 (Regime de Previdência Complementar); Lei Complementar Municipal nº Rondônia , 29 de Outubro de 2026 • Diário Oficial dos Municípios do Estado de Rondônia • ANO XVIII | Nº 4350a - Edição Extraordinária 886/2022 e alterações posteriores (organização do IPAM). Estrutura e competências institucionais do IPAM, custeio, segurados, dependentes, benefícios e assistência à saúde decorrentes dessas normas."}}, "cargos": [{"cod": "T01", "nome": "Técnico Autárquico — Administrativa", "nivel": "medio", "salario": 3000, "horas": 40, "vagas": {"ac": 18, "pcd": 3, "ppp": 6, "ido": 3, "total": 30}, "posicao": {"ac": 195, "pcd": 30, "ppp": 60, "ido": 15}, "especificos": "Rotinas administrativas e atendimento ao público em entidade previdenciária e de assistência à saúde. Atendimento presencial e remoto, escuta, comunicação, orientação ao usuário e tratamento de situações de conflito. Cadastro, conferência, atualização e validação de dados e documentos. Protocolo, autuação, instrução, tramitação, acompanhamento, arquivamento e desarquivamento de processos administrativos físicos e eletrônicos. Noções de gestão documental, temporalidade, classificação, preservação, sigilo e acesso. Redação oficial e elaboração de comunicações, declarações, certidões, despachos, relatórios simples, planilhas e controles. Organização de agendas, reuniões e rotinas de setor. Noções de gestão de materiais, patrimônio, almoxarifado e inventário. Noções de compras e contratos administrativos. Princípios de atendimento na Administração Pública. Previdência do servidor público: filiação, dependentes, benefícios, manutenção e revisão de direitos, recursos administrativos, prova documental, cadastro previdenciário, certidão de tempo de contribuição e compensação previdenciária (Lei Federal nº 9.796/1999), em nível operacional. Assistência à Saúde administrada pelo IPAM: usuários, dependentes, custeio, utilização dos serviços, procedimentos administrativos e orientações gerais. Proteção de dados pessoais, segurança da informação e sigilo funcional aplicados ao atendimento e à gestão de processos."}, {"cod": "T02", "nome": "Técnico Autárquico — Informática", "nivel": "medio", "salario": 3000, "horas": 40, "vagas": {"ac": 3, "pcd": 0, "ppp": 1, "ido": 0, "total": 4}, "posicao": {"ac": 26, "pcd": 4, "ppp": 8, "ido": 2}, "especificos": "Rondônia , 29 de Outubro de 2026 • Diário Oficial dos Municípios do Estado de Rondônia • ANO XVIII | Nº 4350a - Edição Extraordinária Arquitetura e componentes de microcomputadores: processadores, memória, placa-mãe, armazenamento, fontes, interfaces, impressoras e periféricos. Montagem, instalação, configuração, diagnóstico e manutenção preventiva e corretiva de hardware. Sistemas operacionais Windows 10 e 11 e noções de Linux: instalação, atualização, usuários, permissões, serviços, logs, sistemas de arquivos e solução de problemas. Instalação, configuração e atualização de aplicativos, drivers e utilitários. Redes de computadores: modelos OSI e TCP/IP, endereçamento IPv4/IPv6, máscaras, gateway, DNS, DHCP, Ethernet, Wi-Fi, cabeamento, switches, roteadores e compartilhamento de recursos. Noções de VLAN e VPN. Ferramentas de diagnóstico de rede. Segurança de estações e redes: antivírus, firewall, controle de acesso, autenticação, malware, phishing, vulnerabilidades, atualização, criptografia e boas práticas. Backup: tipos, mídias, rotinas, retenção, restauração e verificação. Atendimento e suporte ao usuário: registro, classificação e solução de chamados, inventário de ativos, documentação técnica, orientação e treinamento. Microsoft Office / Microsoft 365 e LibreOffice em nível de suporte. Noções de diretórios e administração de usuários. Noções de virtualização e serviços em nuvem. Noções de banco de dados e SQL. Proteção de dados pessoais e segurança da informação conforme a Lei Federal nº 13.709/2018. Apoio a sistemas corporativos, inclusive sistemas de orçamento, execução financeira e gestão administrativa."}, {"cod": "A01", "nome": "Analista Autárquico — Administração", "nivel": "superior", "salario": 5000, "horas": 40, "vagas": {"ac": 2, "pcd": 0, "ppp": 0, "ido": 0, "total": 2}, "posicao": {"ac": 13, "pcd": 2, "ppp": 4, "ido": 1}, "especificos": "Teorias da Administração e evolução do pensamento administrativo. Funções administrativas: planejamento, organização, direção e controle. Estruturas organizacionais, departamentalização, desenho organizacional e organização e métodos. Planejamento estratégico, tático e operacional. Análise de ambiente, definição de objetivos, indicadores e metas; ferramentas como SWOT e Balanced Scorecard em aplicação ao setor público. Gestão por processos: mapeamento, modelagem, análise, padronização, redesenho, indicadores e melhoria contínua. Gestão da qualidade e excelência em serviços. Gestão de projetos: escopo, prazo, custos, riscos, partes interessadas e acompanhamento. Gestão de pessoas: recrutamento, desenvolvimento, competências, desempenho, liderança, motivação, clima, comunicação e equipes. Logística, compras, estoques, almoxarifado, patrimônio e cadeia de suprimentos. Noções de orçamento, finanças e custos no setor público. Administração de materiais e contratos. Lei Federal nº 14.133/2021: planejamento da contratação, estudos técnicos preliminares, termo de referência, seleção do fornecedor, gestão e fiscalização contratual, alterações e sanções. Governança, gestão de riscos, controles internos, integridade e compliance. Administração Pública e modelos de gestão pública. Gestão de serviços e foco no cidadão. Indicadores de desempenho, análise de dados gerenciais, relatórios, pareceres, planos e projetos. Racionalização, inovação, transformação digital e otimização de rotinas."}, {"cod": "A02", "nome": "Analista Autárquico — Administrativo", "nivel": "superior", "salario": 5000, "horas": 40, "vagas": {"ac": 3, "pcd": 1, "ppp": 1, "ido": 1, "total": 6}, "posicao": {"ac": 39, "pcd": 6, "ppp": 12, "ido": 3}, "especificos": "Regime Próprio de Previdência Social dos servidores públicos: princípios, organização, filiação, segurados e dependentes, custeio, benefícios e regras de concessão. Aposentadorias e pensões no RPPS após a Emenda Constitucional nº 103/2019, observadas as competências dos entes federativos e a legislação municipal. Regras permanentes e de transição aplicáveis ao Município, conforme legislação vigente. Tempo de contribuição, tempo de serviço, averbação, contagem recíproca e Certidão de Tempo de Contribuição. Compensação previdenciária entre regimes: Lei Federal nº 9.796/1999 e regulamentação aplicável. Cadastro previdenciário, prova de vida e gestão de informações de segurados e beneficiários. Processos de reconhecimento inicial, manutenção, revisão, suspensão, cessação e recurso relativos a benefícios. Instrução processual, análise de documentos e cálculos previdenciários em nível compatível com as atribuições do cargo. Prescrição, decadência e revisão de atos administrativos concessórios. Atendimento e orientação previdenciária. Noções de cálculo de proventos, médias contributivas, reajustes e pensões. Gestão e governança do RPPS; equilíbrio financeiro e atuarial; transparência; controles e responsabilidade do gestor. Parcelamento de débitos previdenciários: Emenda Constitucional nº 136/2025 (arts. 115 e 117 do ADCT), em seus aspectos gerais. Lei Federal nº 9.717/1998, Lei Federal nº 10.887/2004 e Portaria MTP nº 1.467/2022 e alterações posteriores. Legislação previdenciária municipal de Porto Velho, especialmente a Lei Complementar Municipal nº 404/2010 e alterações posteriores e as demais normas institucionais do IPAM pertinentes aos benefícios. Processo administrativo, proteção de dados e sigilo na gestão previdenciária."}, {"cod": "A03", "nome": "Analista Autárquico — Auditor Controle Interno", "nivel": "superior", "salario": 5000, "horas": 40, "vagas": {"ac": 2, "pcd": 0, "ppp": 0, "ido": 0, "total": 2}, "posicao": {"ac": 13, "pcd": 2, "ppp": 4, "ido": 1}, "especificos": "Sistema de controle interno na Administração Pública. Constituição Federal, especialmente arts. 70 a 75. Controle interno e externo; controle administrativo, legislativo e judicial. Finalidades, competências e responsabilidades das unidades de controle, auditoria, correição, ouvidoria e integridade. Auditoria governamental: planejamento, matriz de riscos, materialidade, relevância, escopo, testes, amostragem, evidências, papéis de trabalho, achados, causas, efeitos, recomendações, monitoramento e relatórios. Auditoria de conformidade, financeira, contábil, operacional e de desempenho. Controles internos e gestão de riscos: modelo das três linhas e referenciais COSO. Governança, integridade, compliance, prevenção e detecção de fraudes. Segregação de funções. Lei Federal nº 4.320/1964, Lei Complementar nº 101/2000 e noções de contabilidade e orçamento público. Licitações e contratos pela Lei Federal nº 14.133/2021: planejamento, seleção, execução, fiscalização, alterações, pagamentos e sanções sob a ótica do controle. Improbidade administrativa: Lei Federal nº 8.429/1992, com as alterações da Lei Federal nº 14.230/2021. Lei Anticorrupção — Lei Federal nº 12.846/2013. Lei de Acesso à Informação e Lei Geral de Proteção de Dados. Transparência, ouvidoria, controle social, ética e responsabilização. Auditoria e fiscalização da aplicação de recursos previdenciários e assistenciais. Regime Próprio de Previdência Social: governança, custeio, benefícios, investimentos, avaliação atuarial, demonstrativos e controles, conforme a Lei Federal nº 9.717/1998 e a Portaria MTP nº 1.467/2022, com as alterações das Portarias MPS nº 2.010/2025 e nº 2.582/2025 e demais alterações posteriores. Parcelamento de débitos previdenciários: Emenda Constitucional nº 136/2025 (arts. 115 e 117 do ADCT). Organização do Município de Porto Velho: Lei Orgânica do Município, quanto à Administração Pública municipal, à fiscalização e ao controle. Prestação de contas, atuação dos Tribunais de Contas e acompanhamento de recomendações. Elaboração de pareceres, notas técnicas e relatórios de controle."}, {"cod": "A04", "nome": "Analista Autárquico — Auditor Enfermeiro", "nivel": "superior", "salario": 5000, "horas": 40, "vagas": {"ac": 2, "pcd": 0, "ppp": 1, "ido": 0, "total": 3}, "posicao": {"ac": 19, "pcd": 3, "ppp": 6, "ido": 2}, "especificos": "Rondônia , 29 de Outubro de 2026 • Diário Oficial dos Municípios do Estado de Rondônia • ANO XVIII | Nº 4350a - Edição Extraordinária Auditoria em enfermagem e auditoria em serviços de saúde: conceitos, finalidades, métodos, tipos, planejamento, execução, evidências, relatórios, pareceres e monitoramento. Legislação profissional da Enfermagem: Lei Federal nº 7.498/1986 e Decreto Federal nº 94.406/1987. Código de Ética dos Profissionais de Enfermagem (Resolução COFEN nº 564/2017 e alterações posteriores). Resolução COFEN nº 720/2023, quanto à atuação e aos requisitos do enfermeiro auditor, e demais normas do COFEN/COREN aplicáveis à auditoria. Processo de Enfermagem e registros assistenciais. Auditoria de prontuários, anotações, evoluções, prescrições, checagens, diagnósticos, procedimentos e demais documentos de enfermagem. Qualidade, completude, rastreabilidade e validade dos registros. Auditoria concorrente, retrospectiva e prospectiva. Avaliação da pertinência, necessidade e conformidade de procedimentos médicos e de enfermagem. Faturamento e contas hospitalares, reembolsos, coberturas, tabelas de procedimentos, diárias, taxas, materiais, medicamentos e OPME. Glosas técnicas e administrativas, recursos e contestações. Gestão de custos e uso racional de recursos sem comprometimento da qualidade assistencial. Segurança do paciente, gerenciamento de riscos, eventos adversos, protocolos assistenciais, prevenção e controle de infecções e indicadores de qualidade. Vistorias e inspeções em hospitais, clínicas e serviços credenciados. Conformidade sanitária, ética e regulatória. Normas da Agência Nacional de Saúde Suplementar relacionadas à auditoria e à cobertura assistencial, quando aplicáveis ao modelo assistencial do IPAM. Indicadores de desempenho, taxas de complicação, readmissão, permanência e outros parâmetros assistenciais. Educação permanente e capacitação de equipes. Sigilo, prontuário e proteção de dados de saúde. Lei Complementar Municipal nº 841/2021 (Assistência à Saúde e Fundo de Assistência à Saúde — FAS). Integração multiprofissional e elaboração de recomendações para melhoria dos processos assistenciais e controle de custos."}, {"cod": "A05", "nome": "Analista Autárquico — Auditor Médico", "nivel": "superior", "salario": 5000, "horas": 20, "vagas": {"ac": 3, "pcd": 0, "ppp": 1, "ido": 0, "total": 4}, "posicao": {"ac": 26, "pcd": 4, "ppp": 8, "ido": 2}, "especificos": "Auditoria médica e auditoria em saúde: conceitos, objetivos, modalidades, planejamento, execução, registro de achados, pareceres, relatórios, recursos e monitoramento. Ética médica e normas do Conselho Federal de Medicina (CFM) e dos Conselhos Regionais de Medicina aplicáveis à auditoria, em especial o Código de Ética Médica, aprovado pela Resolução CFM nº 2.217/2018 e alterações posteriores, e a Resolução CFM nº 2.448/2025, observados os dispositivos vigentes e as suspensões judiciais aplicáveis, conforme o marco temporal estabelecido no edital. Responsabilidade, sigilo, autonomia profissional, prontuário, consentimento e proteção de dados de saúde. Auditoria de prontuários, fichas clínicas, exames, laudos e documentação assistencial. Medicina baseada em evidências: níveis de evidência, análise crítica e aplicação à avaliação de efetividade, segurança e pertinência de procedimentos. Protocolos médicos e diretrizes clínicas: fundamentos, utilização e avaliação de conformidade na auditoria. Auditoria ambulatorial e hospitalar. Indicação e autorização de internações, cirurgias eletivas, exames, terapias e procedimentos. Análise de contas médicas, faturamento, tabelas de procedimentos, itens assistenciais, diárias, taxas, medicamentos e materiais. Órteses, Próteses e Materiais Especiais (OPME): avaliação da indicação, justificativa técnica, autorização, utilização, documentação comprobatória e cobrança. Glosas, recursos, contestações e prevenção de desperdícios, abusos e fraudes. Noções de gestão em saúde: planejamento, organização de processos assistenciais, gestão de custos, acompanhamento de indicadores e avaliação de resultados. Economia da saúde, farmacoeconomia e avaliação de tecnologias em saúde: conceitos e aplicações à auditoria e ao uso racional dos recursos assistenciais. Noções de cálculos atuariais aplicados ao benefício de assistência à saúde: mutualismo, risco, sinistralidade, precificação, equilíbrio financeiro e interpretação de indicadores e informações atuariais em nível introdutório. Qualidade e segurança do paciente, indicadores assistenciais, eventos adversos, tempo de permanência e utilização de serviços. Vistorias e acompanhamento da rede credenciada. Regulação, avaliação e controle da assistência à saúde. Sistemas de saúde: organização, financiamento e prestação da assistência; relações entre os setores público e privado. Normas da Agência Nacional de Saúde Suplementar relacionadas à auditoria e à cobertura assistencial, quando aplicáveis ao modelo assistencial do Instituto de Previdência e Assistência dos Servidores do Município de Porto Velho (IPAM). Trabalho multiprofissional. Comunicação com usuários, prestadores, médicos assistentes e equipes de saúde. Administração de conflitos e tratamento de divergências técnicas e assistenciais no exercício da auditoria. Legislação aplicada à auditoria médica e à assistência à saúde. Lei Complementar Municipal nº 841/2021 e alterações posteriores: assistência à saúde e Fundo de Assistência à Saúde (FAS). Princípios da Administração Pública aplicados à auditoria dos recursos do FAS. Noções de controles contábeis, orçamentários, financeiros e operacionais relevantes à auditoria em saúde."}, {"cod": "A06", "nome": "Analista Autárquico — Auditor Odontológico", "nivel": "superior", "salario": 5000, "horas": 40, "vagas": {"ac": 1, "pcd": 0, "ppp": 0, "ido": 0, "total": 1}, "posicao": {"ac": 6, "pcd": 1, "ppp": 2, "ido": 1}, "especificos": "Auditoria odontológica: conceitos, objetivos, modalidades, planejamento, análise documental, inspeção, parecer técnico, relatório, recurso e monitoramento. Ética e legislação profissional da Odontologia: Código de Ética Odontológica (Resolução CFO nº 118/2012 e alterações posteriores) e demais normas do Conselho Federal e dos Conselhos Regionais de Odontologia aplicáveis à auditoria, ao prontuário, à responsabilidade profissional e à publicidade. Auditoria da indicação, pertinência, qualidade e conformidade técnica de procedimentos odontológicos propostos e realizados. Prontuário odontológico: identificação, anamnese, diagnóstico, plano de tratamento, evolução, consentimento, exames complementares, imagens e registros. Auditoria de contas odontológicas, faturamento, reembolso, tabelas de procedimentos, materiais, custos, glosas e contestações. Avaliação de tratamentos restauradores, endodônticos, periodontais, cirúrgicos, protéticos, ortodônticos e de diagnóstico, segundo princípios gerais de auditoria e respeitadas as competências profissionais. Biossegurança, segurança do paciente e qualidade assistencial. Vistorias técnicas, credenciamento, monitoramento e avaliação da rede prestadora. Indicadores de qualidade e desempenho. Identificação e documentação de inconsistências, abusos, desperdícios, fraudes e irregularidades. Normas da Agência Nacional de Saúde Suplementar relacionadas à assistência odontológica, quando aplicáveis ao modelo assistencial do IPAM. Proteção de dados pessoais, sigilo e segurança das informações de saúde. Lei Complementar Municipal nº 841/2021 (Assistência à Saúde e Fundo de Assistência à Saúde — FAS). Elaboração de pareceres e suporte técnico à decisão administrativa em recursos e glosas."}, {"cod": "A07", "nome": "Analista Autárquico — Ciências Atuariais", "nivel": "superior", "salario": 5000, "horas": 40, "vagas": {"ac": 1, "pcd": 0, "ppp": 0, "ido": 0, "total": 1}, "posicao": {"ac": 6, "pcd": 1, "ppp": 2, "ido": 1}, "especificos": "Matemática financeira e atuarial. Juros, descontos, rendas, anuidades, sistemas de amortização e equivalência de capitais. Probabilidade e estatística aplicadas: distribuições, esperança, variância, estimação, correlação, regressão e séries temporais, em aplicação atuarial. Tábuas biométricas e de mortalidade, sobrevivência, invalidez e entrada em aposentadoria. Funções biométricas, comutações e rendas contingentes. Modelos de vida e contingências múltiplas. Regimes financeiros de repartição simples, repartição de capitais de cobertura e capitalização. Métodos de financiamento e custeio atuarial. Reservas matemáticas, provisões, passivos atuariais e ativos garantidores. Avaliação atuarial de Regimes Próprios de Previdência Social: hipóteses biométricas, demográficas, econômicas e financeiras; base cadastral; plano de custeio; custo normal e suplementar; resultado atuarial; deficit e superavit; equacionamento; plano de amortização; segregação da massa; fluxos atuariais e projeções. Análise de sensibilidade, aderência de hipóteses, riscos atuariais e qualidade de dados. Gestão integrada de ativos e passivos (ALM): conceito, duração do passivo, compatibilização de fluxos de ativos e obrigações previdenciárias e implicações para a política de investimentos. Política de investimentos dos RPPS: princípios, parâmetros, limites, condições e requisitos das aplicações de recursos, nos termos da Resolução CMN nº 5.272/2025. Portaria MTP nº 1.467/2022, com as alterações das Portarias MPS nº 2.010/2025 e nº 2.582/2025 e demais alterações posteriores: parâmetros e demonstrativos atuariais dos RPPS. Emenda Constitucional nº 103/2019; Emenda Constitucional nº 136/2025 (arts. 115 e 117 do ADCT), quanto ao parcelamento de débitos previdenciários e seus efeitos atuariais; Lei Federal nº 9.717/1998 e legislação previdenciária municipal. Elaboração e interpretação de notas técnicas, relatórios e demonstrativos atuariais. Ética e responsabilidade profissional do atuário."}, {"cod": "A08", "nome": "Analista Autárquico — Ciências Contábeis", "nivel": "superior", "salario": 5000, "horas": 40, "vagas": {"ac": 3, "pcd": 0, "ppp": 1, "ido": 0, "total": 4}, "posicao": {"ac": 26, "pcd": 4, "ppp": 8, "ido": 2}, "especificos": "Contabilidade aplicada ao setor público: objeto, campo de aplicação, princípios e estrutura conceitual. Normas Brasileiras de Contabilidade Aplicadas ao Setor Público — NBC TSP. Plano de Contas Aplicado ao Setor Público — PCASP. Manual de Contabilidade Aplicada ao Setor Público — MCASP, edição vigente na data de publicação do edital. Regimes contábil e orçamentário. Patrimônio público, variações patrimoniais, mensuração, reconhecimento, depreciação, amortização, provisões, passivos e ativos contingentes. Demonstrações contábeis aplicadas ao setor público, consolidação e notas explicativas. Orçamento público: PPA, LDO e LOA; princípios, classificações, créditos adicionais, receita e despesa pública, estágios, restos a pagar, despesas de exercícios anteriores, suprimento de fundos e dívida pública. Lei Federal nº 4.320/1964 e Lei Complementar nº 101/2000. Programação financeira e execução orçamentária. Contabilidade e demonstrações fiscais. SIAFIC e Decreto Federal nº 10.540/2020 e alterações posteriores. Auditoria contábil e financeira: planejamento, evidências, testes, amostragem, achados, relatórios e controles internos. Contabilidade dos RPPS: patrimônio, fundos, provisões e registros específicos; informações contábeis e atuariais; segregação de massas, quando existente; contribuições, parcelamentos e benefícios. Portaria MTP nº 1.467/2022, com as alterações das Portarias MPS nº 2.010/2025 e nº 2.582/2025 e demais alterações posteriores. Parcelamento de débitos previdenciários e seus reflexos contábeis: Emenda Constitucional nº 136/2025 (arts. 115 e 117 do ADCT). Investimentos de RPPS e registros contábeis relacionados, observada a Resolução CMN nº 5.272/2025. Análise econômico-financeira, indicadores, conciliações, fluxo de caixa, controles e prestação de contas. Noções de legislação tributária aplicável à Administração Pública. Responsabilidade, ética e normas profissionais do Conselho Federal de Contabilidade."}, {"cod": "A09", "nome": "Analista Autárquico — Direito", "nivel": "superior", "salario": 5000, "horas": 40, "vagas": {"ac": 2, "pcd": 1, "ppp": 1, "ido": 1, "total": 5}, "posicao": {"ac": 32, "pcd": 5, "ppp": 10, "ido": 3}, "especificos": "Direito Constitucional: princípios fundamentais; direitos e garantias fundamentais; organização do Estado e do Município; Administração Pública; servidores públicos; controle de constitucionalidade: espécies, legitimados, procedimento e efeitos das decisões; fiscalização contábil, financeira e orçamentária; seguridade social e previdência do servidor público. Lei Orgânica do Município de Porto Velho: organização municipal, competências, processo legislativo, Administração Pública municipal e servidores. Direito Administrativo: princípios, organização administrativa, autarquias, poderes administrativos, atos administrativos, agentes públicos, processo administrativo, serviços públicos, responsabilidade civil do Estado, bens públicos, intervenção do Estado na propriedade, controle da Administração, autotutela, prescrição e decadência administrativas. Improbidade administrativa: Lei Federal nº 8.429/1992, com as alterações da Lei Federal nº 14.230/2021. Lei de Acesso à Informação — Lei Federal nº 12.527/2011. Lei Geral de Proteção de Dados — Lei Federal nº 13.709/2018. Licitações e contratos administrativos: Lei Federal nº 14.133/2021 — princípios, planejamento, agentes, estudo técnico preliminar, termo de referência, modalidades, critérios de julgamento, contratação direta, procedimentos auxiliares, habilitação, recursos, contratos, garantias, execução, alteração, extinção, fiscalização, sanções e responsabilização. Convênios, acordos, locações e alienações: conceito, natureza e regime jurídico aplicável. Direito Previdenciário aplicado ao RPPS: Constituição Federal; Emenda Constitucional nº 103/2019; Emenda Constitucional nº 136/2025 (arts. 115 e 117 do ADCT), quanto ao parcelamento de débitos previdenciários; Lei Federal nº 9.717/1998; Lei Federal nº 10.887/2004; Lei Federal nº 9.796/1999 (compensação previdenciária entre regimes); Portaria MTP nº 1.467/2022 e alterações posteriores. Custeio, benefícios, segurados, dependentes, equilíbrio financeiro e atuarial, controle e governança. Legislação previdenciária e de assistência à saúde do Município de Porto Velho: Lei Complementar Municipal nº 385/2010 e alterações posteriores; Lei Complementar Municipal nº 404/2010 e alterações posteriores; Lei Complementar Municipal nº 841/2021; Lei Complementar Municipal nº 866/2021 e alterações posteriores; Lei Complementar Municipal nº 870/2021; Lei Complementar Municipal nº 886/2022 e alterações posteriores. Direito Financeiro: princípios orçamentários, PPA, LDO, LOA, receita e despesa pública, Lei Federal nº 4.320/1964 e Lei Complementar nº 101/2000. Processo Civil aplicado à atuação institucional: jurisdição, competência, partes, atos processuais, prazos, tutela provisória, processo de conhecimento, recursos, cumprimento de sentença e execução — Lei Federal nº 13.105/2015. Mandado de segurança (Lei Federal nº 12.016/2009) e ação civil pública (Lei Federal nº 7.347/1985): cabimento, legitimidade e procedimento. Controle externo e atuação dos Tribunais de Contas, do Ministério Público e demais órgãos de controle. Pesquisa legislativa e jurisprudencial. Técnica de elaboração de pareceres, despachos, contratos, atos normativos e manifestações jurídicas. Compliance, integridade, gestão de riscos jurídicos, controle de prazos e gestão documental. ANEXO IV – DAS ATRIBUIÇÕES DOS CARGOS"}, {"cod": "A10", "nome": "Analista Autárquico — Gestão Financeira", "nivel": "superior", "salario": 5000, "horas": 40, "vagas": {"ac": 1, "pcd": 0, "ppp": 0, "ido": 0, "total": 1}, "posicao": {"ac": 6, "pcd": 1, "ppp": 2, "ido": 1}, "especificos": "Administração financeira: objetivos, decisões de investimento e financiamento, liquidez, capital de giro e gestão de caixa. Matemática financeira: juros simples e compostos, taxas nominais, efetivas e equivalentes, descontos, séries de pagamentos, sistemas de amortização, valor presente e valor futuro. Avaliação econômica de projetos: fluxo de caixa, valor presente líquido, taxa interna de retorno, payback e análise de sensibilidade. Análise de demonstrações e indicadores econômico-financeiros. Planejamento, orçamento e controle financeiro. Finanças públicas: PPA, LDO, LOA, receita e despesa pública, programação financeira, cronograma de desembolso, restos a pagar e responsabilidade fiscal. Lei Federal nº 4.320/1964 e Lei Complementar nº 101/2000. Elaboração, revisão e acompanhamento da programação orçamentária e financeira. Projeção de receitas e despesas. Relatórios gerenciais e análise de execução. Gestão financeira de contratos e convênios. Tesouraria, conciliações e controles. Noções de mercado financeiro aplicáveis à gestão de recursos previdenciários: segmentos de renda fixa e renda variável, fundos de investimento, títulos públicos, risco, Rondônia , 29 de Outubro de 2026 • Diário Oficial dos Municípios do Estado de Rondônia • ANO XVIII | Nº 4350a - Edição Extraordinária retorno, liquidez e diversificação. Gestão de recursos dos RPPS: política de investimentos, princípios, parâmetros, limites, condições e requisitos das aplicações, governança, credenciamento de instituições, controle de riscos e acompanhamento da carteira, nos termos da Resolução CMN nº 5.272/2025 e da Portaria MTP nº 1.467/2022 e alterações posteriores. Equilíbrio financeiro e atuarial, fluxo de benefícios e gestão integrada de ativos e passivos (ALM): conceito e finalidade. Integridade, controles internos, segregação de funções e prestação de contas na gestão de recursos públicos."}, {"cod": "A11", "nome": "Analista Autárquico — Médico Perito", "nivel": "superior", "salario": 5000, "horas": 20, "vagas": {"ac": 3, "pcd": 0, "ppp": 1, "ido": 0, "total": 4}, "posicao": {"ac": 26, "pcd": 4, "ppp": 8, "ido": 2}, "especificos": "Perícia médica: princípios, finalidade, metodologia, independência técnica, documentação, exame pericial, anamnese, exame físico, análise de exames complementares, conclusão e elaboração de laudo ou parecer. Ética médica e normas do Conselho Federal de Medicina e dos Conselhos Regionais de Medicina aplicáveis à perícia, em especial o Código de Ética Médica (Resolução CFM nº 2.217/2018 e alterações posteriores). Sigilo, consentimento, prontuário, documentos médicos, atestados e proteção de dados pessoais de saúde. Capacidade e incapacidade laborativa: conceitos, graus, duração, data de início, prognóstico, limitações funcionais, possibilidade de reabilitação e readaptação. Incapacidade permanente para fins previdenciários e assistenciais. Relação entre doença, deficiência, funcionalidade e trabalho. Classificação Internacional de Funcionalidade, Incapacidade e Saúde (CIF): estrutura e aplicação. Avaliação da deficiência e de sua compatibilidade com as atribuições do cargo: Lei Federal nº 13.146/2015 (Lei Brasileira de Inclusão), Decreto Federal nº 3.298/1999 e Decreto Federal nº 9.508/2018. Inspeção de ambiente e posto de trabalho em contexto pericial. Nexo causal e concausal: conceito, critérios de caracterização e repercussão na conclusão pericial. Saúde do trabalhador, riscos ocupacionais, ergonomia e prevenção. Doenças e condições de maior relevância pericial: musculoesqueléticas, psiquiátricas, neurológicas, cardiovasculares, respiratórias, oncológicas, infectocontagiosas, endócrino-metabólicas e decorrentes de acidentes, com foco em repercussão funcional e laboral. Regime Próprio de Previdência Social: benefícios por incapacidade, aposentadoria por incapacidade permanente e pensão, quando relacionados à avaliação médico-pericial; Emenda Constitucional nº 103/2019, Lei Federal nº 9.717/1998, Portaria MTP nº 1.467/2022 e alterações posteriores e legislação municipal aplicável. Revisão de aposentadorias por incapacidade, quando prevista. Elaboração de parecer conclusivo, fundamentação técnico-científica, comunicação de resultados e participação em juntas e recursos."}, {"cod": "A12", "nome": "Analista Autárquico — Serviço Social", "nivel": "superior", "salario": 5000, "horas": 40, "vagas": {"ac": 2, "pcd": 0, "ppp": 0, "ido": 0, "total": 2}, "posicao": {"ac": 13, "pcd": 2, "ppp": 4, "ido": 1}, "especificos": "Fundamentos históricos, teórico-metodológicos e ético-políticos do Serviço Social. Questão social, direitos sociais, cidadania e políticas públicas. Projeto ético-político profissional. Lei Federal nº 8.662/1993 (regulamentação da profissão) e Código de Ética Profissional do Assistente Social (Resolução CFESS nº 273/1993 e alterações posteriores). Lei Federal nº 12.317/2010 (jornada de trabalho do assistente social) e demais normas do CFESS/CRESS pertinentes ao exercício profissional. Seguridade Social na Constituição Federal: saúde, previdência e assistência social. Política de Previdência Social e trabalho do assistente social no campo previdenciário. Regime Próprio de Previdência Social e proteção social do servidor público. Lei Orgânica da Assistência Social — Lei Federal nº 8.742/1993 e noções do SUAS. Lei Brasileira de Inclusão — Lei Federal nº 13.146/2015. Estatuto da Pessoa Idosa — Lei Federal nº 10.741/2003. Família, trabalho, envelhecimento, deficiência, vulnerabilidade, violências, diversidade e redes de proteção. Estudo social, entrevista, visita domiciliar e institucional, observação, parecer social, relatório, laudo e registro técnico. Planejamento, elaboração, execução, monitoramento e avaliação de planos, programas e projetos sociais. Trabalho interdisciplinar e intersetorial. Educação social e orientação de direitos e deveres. Gestão de benefícios, serviços e recursos sociais. Pesquisa social e indicadores. Sigilo profissional, prontuários e proteção de dados pessoais. Participação e controle social. Política de saúde e assistência à saúde do servidor no contexto do IPAM. Aplicação da legislação municipal previdenciária e de assistência à saúde às ações de orientação, acompanhamento e garantia de direitos dos usuários."}, {"cod": "A13", "nome": "Analista Autárquico — Tecnologia da Informação", "nivel": "superior", "salario": 5000, "horas": 40, "vagas": {"ac": 2, "pcd": 0, "ppp": 0, "ido": 0, "total": 2}, "posicao": {"ac": 13, "pcd": 2, "ppp": 4, "ido": 1}, "especificos": "Engenharia de software: ciclo de vida, requisitos, análise, projeto, arquitetura, desenvolvimento, testes, implantação, manutenção e documentação. Métodos ágeis, Scrum, Kanban, integração e entrega contínuas, versionamento e DevOps. Modelagem de sistemas e noções de UML. Arquiteturas de aplicações, APIs, serviços web, microsserviços e integração de sistemas. Bancos de dados relacionais e não relacionais: modelagem, normalização, SQL, transações, integridade, índices, backup, recuperação e desempenho. Sistemas operacionais Windows Server e Linux: serviços, usuários, permissões, logs e administração. Redes: modelos OSI e TCP/IP, IPv4/IPv6, roteamento, switching, VLAN, DNS, DHCP, VPN, Wi-Fi e serviços de rede. Infraestrutura, virtualização, containers, armazenamento, alta disponibilidade, monitoramento e computação em nuvem. Segurança da informação e cibernética: gestão de riscos, identidade e acesso, criptografia, certificados, vulnerabilidades, hardening, gestão de logs, monitoramento e correlação de eventos de segurança (SIEM): finalidade, componentes e aplicação; resposta a incidentes, continuidade, backup e recuperação de desastres. ISO/IEC 27001 e ISO/IEC 27002: estrutura, objetivos e controles. Proteção de dados pessoais e Lei Federal nº 13.709/2018. Governança e gestão de TI: COBIT 2019, ITIL 4, gestão de serviços, catálogo, incidentes, problemas, mudanças, configuração, níveis de serviço e ativos. Gestão de projetos de TI. Contratação de soluções de TIC no setor público: planejamento, requisitos, riscos, fiscalização e gestão contratual à luz da Lei Federal nº 14.133/2021. Interoperabilidade, acessibilidade digital e governo digital. Suporte, gestão de infraestrutura e continuidade dos serviços críticos de uma autarquia previdenciária e de assistência à saúde."}]};
CONC.editais.pf = {"titulo": "Edital PF nº 1/2025 (Cebraspe): referência para o próximo concurso", "fonte": "Edital de abertura PF 2025 (Cebraspe). O novo edital pode mudar tudo: use como referência.", "link": "https://www.cebraspe.org.br/concursos/pf_25", "linkNovo": "https://www.gov.br/pf", "regras": ["Prova objetiva P1 de Agente, Escrivão e Papiloscopista: 120 itens CERTO ou ERRADO, valendo 120 pontos (item 8.1 e 7.1.3).", "Estrutura: Bloco I (conhecimentos básicos) 60 itens; Bloco II (conhecimentos básicos) 36 itens; Bloco III (conhecimentos específicos) 24 itens.", "Pontuação (8.11.2): certo = +1,00; errado = −1,00 (um erro anula um acerto); em branco ou marcação dupla (C e E) = 0,00.", "Para pontuar, marque um e somente um dos dois campos, C ou E (8.3). Marcação rasurada ou emendada vale como indevida (8.5).", "Eliminação na objetiva (8.11.6): menos de 6,00 pontos no Bloco I, OU menos de 3,00 no Bloco II, OU menos de 2,00 no Bloco III, OU menos de 48,00 no conjunto dos três blocos.", "Tempo (7.3): 4 horas e 30 minutos para a prova objetiva e a discursiva juntas, no turno da tarde.", "Prova discursiva P2: um texto dissertativo de até 30 linhas (7.1.3). Só é corrigida para quem passa na objetiva.", "Depois: exame de aptidão física, avaliação médica, avaliação psicológica e investigação social (todas eliminatórias).", "A folha de respostas é o único documento válido (8.4); quem não a devolver tem a prova anulada (8.9)."], "estrutura": [["Bloco I: Língua Portuguesa, Direito Administrativo, Direito Constitucional, Direito Penal e Processual Penal, Direitos Humanos, Legislação Especial, Estatística e Raciocínio Lógico", 60, "itens"], ["Bloco II: Informática", 36, "itens"], ["Bloco III: Contabilidade Geral (Agente)", 24, "itens"]], "blocos": {"BLOCO I": {"LÍNGUA PORTUGUESA": "1 Compreensão e interpretação de textos de gêneros variados. 2 Reconhecimento de tipos e gêneros textuais. 3 Domínio da ortograﬁa oﬁcial. 4 Domínio dos mecanismos de coesão textual. 4.1 Emprego de elementos de referenciação, substituição e repetição, de conectores e de outros elementos de sequenciação textual. 4.2 Emprego de tempos e modos verbais. 5 Domínio da estrutura morfossintática do período. 5.1 Emprego das classes de palavras. 5.2 Relações de coordenação entre orações e entre termos da oração. 5.3 Relações de subordinação entre orações e entre termos da oração. 5.4 Emprego dos sinais de pontuação. 5.5 Concordância verbal e nominal. 5.6 Regência verbal e nominal. 5.7 Emprego do sinal indicativo de crase. 5.8 Colocação dos pronomes átonos. 6 Reescrita de frases e parágrafos do texto. 6.1 Signiﬁcação das palavras. 6.2 Substituição de palavras ou de trechos de texto. 6.3 Reorganização da estrutura de orações e de períodos do texto. 6.4 Reescrita de textos de diferentes gêneros e níveis de formalidade. 7 Correspondência oﬁcial (conforme Manual de Redação da Presidência da República). 7.1 Aspectos gerais da redação oﬁcial. 7.2 Finalidade dos expedientes oﬁciais. 7.3 Adequação da linguagem ao tipo de documento. 7.4 Adequação do formato do texto ao gênero.", "NOÇÕES DE DIREITO ADMINISTRATIVO": "1 Noções de organização administrativa. 1.1 Centralização, descentralização, concentração e desconcentração. 1.2 Administração direta e indireta. 1.3 Autarquias, fundações, empresas públicas e sociedades de economia mista. 2 Ato administrativo. 2.1 Conceito, requisitos, atributos, classiﬁcação e espécies. 3 Agentes públicos. 3.1 Legislação pertinente. 3.1.1 Lei nº 8.112/1990 e suas alterações. 3.1.2 Disposições constitucionais aplicáveis. 3.2 Disposições doutrinárias. 3.2.1 Conceito. 3.2.2 Espécies. 3.2.3 Cargo, emprego e função pública. 4 Poderes administrativos. 4.1 Hierárquico, disciplinar, regulamentar e de polícia. 4.2 Uso e abuso do poder. 5 Licitação. 5.1 Princípios. 5.2 Contratação direta: dispensa e inexigibilidade. 5.3 Modalidades. 5.4 Tipos. 5.5 Procedimento. 6 Controle da Administração Pública. 6.1 Controle exercido pela Administração Pública. 6.2 Controle judicial. 6.3 Controle legislativo. 7 Responsabilidade civil do Estado. 7.1 Responsabilidade civil do Estado no direito brasileiro. 7.1.1 Responsabilidade por ato comissivo do Estado. 7.1.2 Responsabilidade por omissão do Estado. 7.2 Requisitos para a demonstração da responsabilidade do Estado. 7.3 Causas excludentes e atenuantes da responsabilidade do Estado. 8 Regime jurídico‐administrativo. 8.1 Conceito. 8.2 Princípios expressos e implícitos da Administração Pública.", "NOÇÕES DE DIREITO CONSTITUCIONAL": "1 Direitos e garantias fundamentais: direitos e deveres individuais e coletivos; direito à vida, à liberdade, à igualdade, à segurança e à propriedade; direitos sociais; nacionalidade; cidadania e direitos políticos; partidos políticos; garantias constitucionais individuais; garantias dos direitos coletivos, sociais e políticos. 2 Poder Executivo: forma e sistema de governo; cheﬁa de Estado e cheﬁa de governo. 3 Defesa do Estado e das instituições democráticas: segurança pública; organização da segurança pública. 4 Ordem social: base e objetivos da ordem social; seguridade social; meio ambiente; família, criança, adolescente, idoso, indígenas.", "NOÇÕES DE DIREITO PENAL E DE DIREITO PROCESSUAL PENAL": "1 Princípios básicos. 2 Aplicação da lei penal. 2.1 A lei penal no tempo e no espaço. 2.2 Tempo e lugar do crime. 2.3 Territorialidade e extraterritorialidade da lei penal. 3 O fato típico e seus elementos. 3.1 Crime consumado e tentado. 3.2 Ilicitude e causas de exclusão. 3.3 Excesso punível. 4 Crimes contra a pessoa. 5 Crimes contra o patrimônio. 6 Crimes contra a fé pública. 7 Crimes contra a Administração Pública. 8 Inquérito policial. 8.1 Histórico, natureza, conceito, ﬁnalidade, características, fundamento, titularidade, grau de cognição, valor probatório, formas de instauração, notitia criminis, delatio criminis, procedimentos investigativos, indiciamento, garantias do investigado; conclusão. 9 Prova. 9.1 Preservação de local de crime. 9.2 Requisitos e ônus da prova. 9.3 Nulidade da prova. 9.4 Documentos de prova. 9.5 Reconhecimento de pessoas e coisas. 9.6 Acareação. 9.7 Indícios. 9.8 Busca e apreensão. 10 Restrição de liberdade. 10.1 Prisão em flagrante.", "DIREITOS HUMANOS": "1 Direitos humanos na Constituição Federal de 1988. 2 Sistema internacional de proteção dos direitos humanos. 3 Convenção para a Prevenção e Punição ao Crime de Genocídio. 4 Convenção Relativa ao Estatuto dos Refugiados. Protocolo sobre o Estatuto dos Refugiados. 5 Convenção sobre a Eliminação de Todas as Formas de Discriminação Racial. 6 Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher. 7 Convenção contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes. 8 Convenção Internacional para a Proteção de Todas as Pessoas contra o Desaparecimento Forçado. 9 Regras mínimas da ONU para o tratamento de pessoas presas. 10 Princípios Básicos sobre o Uso da Força e Armas de Fogo (adotado pelo 8º Congresso das Nações Unidas para a Prevenção do Crime e o Tratamento dos Delinquentes, em Havana, Cuba, de 27 de agosto a 07 de setembro de 1990). 11 Lei nº 13.060, de 22 de dezembro de 2014 - Disciplina o uso dos instrumentos de menor potencial ofensivo pelos agentes de segurança pública, em todo o território nacional. 12. Decreto nº 12.341, de 23 de dezembro de 2024 - Regulamenta a Lei nº 13.060, de 22 de dezembro de 2014, para disciplinar o uso da força e dos instrumentos de menor potencial ofensivo pelos profissionais de segurança pública.", "LEGISLAÇÃO ESPECIAL": "1 Lei 14.967/2024 (Estatuto da Segurança Privada e da Segurança das Instituições Financeiras). 2 Lei nº 10.357/2001 (Normas de controle e fiscalização de produtos químicos). 3 Lei nº 13.445/2017 (Lei de migração). 4 Lei nº 11.343/2006 (normas de repressão ao tráfico ilícito de drogas) e suas alterações (aspectos penais e processuais penais). 5 Lei nº 9.455/1997 (crimes de tortura) e suas alterações (aspectos penais e processuais penais). 6 Lei nº 8.069/1990 (ECA) e suas alterações (aspectos penais e processuais penais). 7 Lei nº 10.826/2003 (Normas sobre registro, posse e comercialização de arma de fogo) e suas alterações (aspectos penais e processuais penais). 8 Lei nº 9.605/1998 (infrações ambientais) e suas alterações (aspectos penais e processuais penais). 9 Lei nº 10.446/2002 (infrações de repercussão interestadual ou internacional) e suas alterações. 10 Lei nº 13.444/2017 (identiﬁcação Civil Nacional). 11 Lei nº 14.534/2023 (adota CPF como nº identiﬁcação). 12 Lei nº 7.116/1983 (Carteira de Identidade) e Decreto nº 10.977/2022 (regulamenta a Lei nº 7.116/1983). 13 Decreto nº 11.797/2023 (serviço de identiﬁcação do cidadão). 14 Lei nº 9.545/1997 (institui o número único de registro de identidade civil). 15 Decreto nº 11.491/2023 (Convenção sobre o Crime Cibernético).", "ESTATÍSTICA": "1 Estatística descritiva e análise exploratória de dados: gráﬁcos, diagramas, tabelas, medidas descritivas (posição, dispersão, assimetria e curtose). 2 Probabilidade. 2.1 Probabilidade e Probabilidade Condicional. 2.2 Conceitos básicos de probabilidade. 2.3 Cálculo de probabilidades condicionais. 2.4 Deﬁnições básicas e axiomas. 2.5 Probabilidade condicional e independência. 2.6 Variáveis aleatórias discretas e contínuas. 2.7 Distribuição de probabilidades. 2.8 Função de probabilidade. 2.9 Função densidade de probabilidade. 2.10 Esperança e momentos. 2.11 Distribuições especiais. 2.12 Distribuições condicionais e independência. 2.13 Transformação de variáveis. 2.14 Leis dos grandes números. 2.15 Teorema central do limite. 2.16 Amostras aleatórias. 2.17 Distribuições amostrais. 2.18 Independência de Eventos, Regra de Bayes e Teorema da Probabilidade Total. 2.19 Conceito de independência. 2.20 Aplicação da regra de Bayes. 2.21 Uso do teorema da probabilidade total. 2.21 Variáveis Aleatórias e Funções de Probabilidade. 2.21.1 Deﬁnição e exemplos de variáveis aleatórias. 2.21.2 Função de probabilidade (para variáveis discretas) e função densidade de probabilidade (para variáveis contínuas). 2.22 Principais Distribuições de Probabilidade Discretas e Contínuas. 2.22.1 Distribuição uniforme. 2.22.2 Distribuição de Bernoulli. 2.22.3 Distribuição binomial. 2.22.4 Distribuição normal. 2.23 Medidas de Tendência Central. 2.23.1 Média (aritmética, ponderada, geométrica e harmônica). 2.23.2 Mediana. 2.23.3 Moda. 2.24 Medidas de Dispersão. 2.24.1 Amplitude. 2.24.2 Variância. 2.24.3 Desvio padrão. 2.24.4 Coeﬁciente de variação. 2.25 Coeﬁciente de Correlação de Pearson. 2.25.1 Conceito e cálculo da correlação entre duas variáveis. 2.26 Teorema Central do Limite. 2.26.1 Importância do teorema para a distribuição amostral da média. 2.27 Regra Empírica (Regra dos Três Sigma) da Distribuição Normal. 2.27.1 Aproximação da dispersão dos dados na distribuição normal. 2.28 Técnicas de Amostragem. 2.29 Amostragem aleatória simples, estratiﬁcada, sistemática e por conglomerados. 2.29.1 Conceitos básicos para determinação do tamanho amostral. 3 Inferência estatística. 3.1 Estimação pontual: métodos de estimação, propriedades dos estimadores, suﬁciência. 3.2 Estimação intervalar: intervalos de conﬁança, intervalos de credibilidade. 3.3 Testes de hipóteses: hipóteses simples e compostas, níveis de signiﬁcância e potência de um teste, teste t de Student, teste qui‐quadrado. 4 Análise de regressão linear. 4.1 Critérios de mínimos quadrados e de máxima verossimilhança. 4.2 Modelos de regressão linear. 4.3 Inferência sobre os parâmetros do modelo. 4.4 Análise de variância. 4.5 Análise de resíduos. 5 Técnicas de amostragem: amostragem aleatória simples, estratiﬁcada, sistemática e por conglomerados. 5.1 Tamanho amostral.", "RACIOCÍNIO LÓGICO": "1 Estruturas lógicas. 2 Lógica de argumentação: analogias, inferências, deduções e conclusões. 3 Lógica sentencial (ou proposicional). 3.1 Proposições simples e compostas. 3.2 Tabelas verdade. 3.3 Equivalências. 3.4 Leis de Morgan. 3.5 Diagramas lógicos. 4 Lógica de primeira ordem. 5 Princípios de contagem e probabilidade. 6 Operações com conjuntos. 7 Raciocínio lógico envolvendo problemas aritméticos, geométricos e matriciais."}, "BLOCO II": {"INFORMÁTICA": "1 Conceito de internet e intranet. 2 Conceitos e modos de utilização de tecnologias, ferramentas, aplicativos e procedimentos associados a internet/intranet. 2.1 Ferramentas e aplicativos comerciais de navegação, de correio eletrônico, de grupos de discussão, de busca, de pesquisa e de redes sociais. 2.2 Noções de sistema operacional (ambiente Linux e Windows). 2.3 Acesso à distância a computadores, transferência de informação e arquivos, aplicativos de áudio, vídeo e multimídia. 2.4 Edição de textos, planilhas e apresentações (ambientes Microsoft Office e LibreOffice). 3 Redes de computadores. 3.1 Formação de endereços IPV4 e IPV6. 4 Conceitos de proteção e segurança. 4.1 Noções de vírus, worms e pragas virtuais. 4.2 Aplicativos para segurança (antivírus, firewall, anti-spyware etc.). 5 Computação na nuvem (cloud computing). 6 Fundamentos da Teoria Geral de Sistemas. 6.1 Camadas de Aplicação, processos, frontend, backend. 7 Sistemas de informação. 7.1 Fases e etapas de sistema de informação. 7.2 Análise de requisitos, especificação, ambientes de testes, homologação, produção e suporte. 8 Teoria da informação. 8.1 Conceitos de informação, dados, representação de dados, de conhecimentos, segurança e inteligência. 9 Banco de dados. 9.1 Base de dados, documentação e prototipação. 9.2 Modelagem conceitual: abstração, modelo entidade-relacionamento, análise funcional e administração de dados. 9.3 Dados estruturados e não estruturados. 9.4 Banco de dados relacionais: conceitos básicos e características. 9.5 Chaves e relacionamentos. 9.6 Noções de mineração de dados: conceituação e características. 9.7 Noções de aprendizado de máquina. 9.8 Noções de Big data: conceito, premissas e aplicação. 10 Redes de comunicação. 10.1 Introdução a redes (computação/telecomunicações). 10.2 Camada física, de enlace de dados e subcamada de acesso ao meio. 10.3 Noções básicas de transmissão de dados: tipos de enlace, códigos, modos e meios de transmissão. 11 Redes de computadores: locais, metropolitanas e de longa distância. 11.1 Terminologia e aplicações, topologias, modelos de arquitetura (OSI/ISO e TCP/IP) e protocolos. 11.2 Interconexão de redes, nível de transporte. 12 Noções de programação Python e R. 13 Metadados de arquivos. 14 Formatos de arquivos de intercâmbio entre sistemas biométricos: NIST, XML, JSON. 15 Testes de acurácia do NIST.GOV. 15.1 Conceitos de falso positivo e falso negativo (FPIR e FNIR). 16 Inteligência Artificial (IA). 16.1 Conceitos de Machine Learning. 16.2 Principais ferramentas de mercado (Copilot, ChatGPT, META). 17 Tecnologias, Ferramentas e Aplicativos. 17.1 Noções de sistema operacional (ambiente Linux e Windows). 17.2 Noções de acesso remoto a computadores, transferência de arquivos, comunicação multimídia e colaboração online (Microsoft Teams). 18 Noções de Redes e Comunicação. 18.1 Conceito de Internet e Intranet. 18.2 Noções de arquitetura e princípios de funcionamento das redes. 18.3 Tipos de redes: locais (LAN), metropolitanas (MAN) e de longa distância (WAN). 18.4 Modelo OSI/ISO e modelo TCP/IP: camadas, funções e protocolos associados. 18.5 Protocolos de comunicação: Ethernet, IP (IPv4 e IPv6), TCP, UDP, DNS, DHCP e SNMP. 18.6 Protocolos e mecanismos de segurança: VPN, SSL/TLS. 18.7 Redes sem fio: padrões IEEE 802.11, WPA/WPA2, segurança e boas práticas. 19 Noções de Computação em Nuvem. 19.1 Definição e características das nuvens privadas e públicas. 19.2 Modelos de Serviço em Nuvem: Infraestrutura como Serviço (IaaS), Plataforma como Serviço (PaaS) e Software como Serviço (SaaS). 20 Conceitos de Proteção e Segurança. 20.1 Ameaças digitais e malwares: noções de vírus, worms, trojans, ransomware, spyware, rootkits, botnets e outras pragas virtuais. 20.2 Ferramentas e técnicas de segurança: uso de antivírus, firewall, anti-spyware e autenticação multifator (MFA). 20.3 Noções de criptografia e proteção de dados: hash criptográfico (MD5, SHA-1, SHA-256), assinaturas digitais. 20.4 Noções de Controle de acesso e autenticação. 21 Dados. 21.1 Banco de dados relacionais: conceitos básicos e características. 21.2 Noções de linguagem SQL. 21.3 Modelagem conceitual: entidades, atributos e relacionamentos. 21.4 Dados estruturados e não estruturados. 21.5 Conceito de DataWarehouse, DataMart, DataLake, DataMesh. 21.6 Metadados. 22 Noções de análise de dados. 22.1 Mineração de dados: conceituação e características. 22.2 Noções de Business Intelligence: Ferramentas e aplicabilidade. 22.3 Noções de aprendizado de máquina, inteligência artificial. 22.4 Noções de big data: conceito, premissas e aplicação. 23 Noções de Programação e Interoperabilidade. 23.1 Noções de programação em Python. 23.2 Conceito de API (Application Programming Interface). 23.3 ETL/ELT (Extract, Transform, Load)."}, "BLOCO III": {"CONTABILIDADE GERAL": "1 Conceitos, objetivos e finalidades da contabilidade. 2 Patrimônio: componentes, equação fundamental do patrimônio, situação líquida, representação gráfica. 3 Atos e fatos administrativos: conceitos, fatos permutativos, modificativos e mistos. 4 Contas: conceitos, contas de débitos, contas de créditos e saldos. 5 Plano de contas: conceitos, elenco de contas, função e funcionamento das contas. 6 Escrituração: conceitos, lançamentos contábeis, elementos essenciais, fórmulas de lançamentos, livros de escrituração, métodos e processos, regime de competência e regime de caixa. 7 Contabilização de operações contábeis diversas: juros, descontos, tributos, aluguéis, variação monetária/ cambial, folha de pagamento, compras, vendas e provisões, depreciações e baixa de bens. 8 Balancete de verificação: conceitos, modelos e técnicas de elaboração. 9 Balanço patrimonial: conceitos, objetivo, composição. 10 Demonstração de resultado de exercício: conceito, objetivo, composição. 11 Lei nº 6.404/1976 e suas alterações, legislação complementar e pronunciamentos do Comitê de Pronunciamentos Contábeis (CPC). 12 Norma Brasileira de Contabilidade - NBC TSP Estrutura Conceitual, de 23 de setembro de 2016."}}};
